# =============================================================================
# MANUAL PARA REGISTRO — DIPOVA / SEAGRI-DF (Versão 2026)
# App Shiny interativo — versão navegável em página única com menu lateral
# Tema visual: cinza grafite + dourado (paleta profissional/elegante)
#
# SOBRE OS SELOS (ETAPA FINAL):
# A seção final mantém apenas as orientações escritas e a base legal,
# sem exibir imagens dos modelos de selo.
#
# Para rodar: abra este arquivo no RStudio e clique em "Run App"
# Pacotes necessários: shiny
# (instale com install.packages("shiny") caso necessário)
# =============================================================================

library(shiny)

# -----------------------------------------------------------------------------
# 1. PALETA DE CORES (tema verde claro institucional + dourado elegante)
# -----------------------------------------------------------------------------
cor_grafite_escuro <- "#1B4332"  # verde bem escuro, cor principal
cor_grafite_medio  <- "#89C29A"  # verde claro, institucional
cor_grafite_claro  <- "#EDF7F0"  # fundo suave verde bem claro
cor_dourado        <- "#C9A24B"  # dourado elegante (destaques)
cor_dourado_escuro <- "#9C7A2E"
cor_creme          <- "#FDFDFC"  # fundo geral da página (neutro, quase branco)
cor_texto          <- "#232327"
cor_alerta_bg      <- "#FDF3E4"
cor_alerta_borda   <- "#C9A24B"
cor_perigo_bg      <- "#FBEAEA"
cor_perigo_borda   <- "#B24444"
cor_info_bg        <- "#EAF1F7"
cor_info_borda     <- "#3E6FA0"

# Links oficiais do conteúdo original
link_pasta_formularios <- "https://drive.google.com/drive/folders/19pv5Lx-7ynTH61RRPAw2P26XudYywaJV?usp=sharing"
link_requerimentos <- link_pasta_formularios
link_projeto <- link_pasta_formularios
link_memorial <- link_pasta_formularios
link_rotulos <- link_pasta_formularios
link_guia_rotulos <- link_pasta_formularios
link_seagri <- "https://www.seagri.df.gov.br"
link_rtiq <- "https://www.gov.br/agricultura/pt-br/assuntos/inspecao/produtos-animal/legislacao/legislacao"
email_geinsp <- "geinsp@seagri.df.gov.br"

# -----------------------------------------------------------------------------
# 2. FUNÇÃO AUXILIAR — desenha um "badge" numerado circular (estilo do índice)
# -----------------------------------------------------------------------------
badge_numero <- function(n) {
  tags$span(
    style = sprintf(
      "display:inline-flex;align-items:center;justify-content:center;
       width:34px;height:34px;border-radius:50%%;
       background:%s;
       color:#fff;font-weight:700;font-size:14px;margin-right:12px;
       box-shadow:0 2px 6px rgba(0,0,0,0.25); flex-shrink:0;", cor_grafite_escuro
    ),
    sprintf("%02d", n)
  )
}

# -----------------------------------------------------------------------------
# 3. FUNÇÃO AUXILIAR — caixa de destaque (dica / atenção / info)
# -----------------------------------------------------------------------------
caixa_destaque <- function(titulo, ..., tipo = c("dica", "atencao", "perigo", "info")) {
  tipo <- match.arg(tipo)
  estilos <- list(
    dica    = list(bg = cor_grafite_claro, borda = cor_grafite_medio, icone = "\U0001F4A1"),
    atencao = list(bg = cor_alerta_bg,   borda = cor_alerta_borda, icone = "\u26A0\uFE0F"),
    perigo  = list(bg = cor_perigo_bg,   borda = cor_perigo_borda, icone = "\u26D4"),
    info    = list(bg = cor_info_bg,     borda = cor_info_borda,  icone = "\u2139\uFE0F")
  )
  e <- estilos[[tipo]]
  div(
    style = sprintf(
      "background:%s; border-left:5px solid %s; border-radius:10px;
       padding:16px 18px; margin:14px 0;", e$bg, e$borda
    ),
    tags$strong(paste(e$icone, titulo)),
    div(style = "margin-top:6px; line-height:1.55;", ...)
  )
}

# -----------------------------------------------------------------------------
# 4. FUNÇÃO AUXILIAR — checklist com "check" dourado
# -----------------------------------------------------------------------------
item_check <- function(...) {
  div(
    style = "display:flex; align-items:flex-start; margin-bottom:10px;",
    tags$span(
      style = sprintf(
        "min-width:24px;height:24px;border-radius:50%%;background:%s;
         color:#fff;display:flex;align-items:center;justify-content:center;
         font-size:13px;font-weight:700;margin-right:10px;margin-top:2px;flex-shrink:0;",
        cor_dourado_escuro
      ), "\u2713"
    ),
    div(style = "line-height:1.5;", ...)
  )
}

# -----------------------------------------------------------------------------
# 5. FUNÇÃO AUXILIAR — cartão de link para download / formulário
# -----------------------------------------------------------------------------
cartao_link <- function(titulo, url) {
  div(
    style = sprintf(
      "background:%s; border:1px solid %s33; border-radius:12px;
       padding:14px 18px; margin:10px 0; display:flex; justify-content:space-between;
       align-items:center; flex-wrap:wrap; gap:10px;", cor_grafite_claro, cor_grafite_medio
    ),
    div(
      tags$div(style = sprintf("font-weight:700;color:%s;", cor_grafite_escuro), titulo),
      tags$a(href = url, target = "_blank", style = sprintf("color:%s;font-size:13px;word-break:break-all;", cor_dourado_escuro), url)
    ),
    tags$a(
      href = url, target = "_blank", class = "btn-link-dourado",
      "\U0001F517 Acessar"
    )
  )
}

# -----------------------------------------------------------------------------
# 6. FUNÇÃO AUXILIAR — tabela estilizada simples a partir de uma matriz/lista
# -----------------------------------------------------------------------------
tabela_estilizada <- function(cabecalho, linhas) {
  tags$table(
    class = "tabela-manual",
    tags$thead(
      tags$tr(lapply(cabecalho, function(h) tags$th(h)))
    ),
    tags$tbody(
      lapply(linhas, function(linha) {
        tags$tr(lapply(linha, function(cel) tags$td(cel)))
      })
    )
  )
}

# -----------------------------------------------------------------------------
# 7. SELOS DA INSPEÇÃO DISTRITAL — desenhados em SVG (texto sobre caminho)
#    Cada selo recebe um "id_base" ÚNICO para evitar conflito de <path> no DOM
# -----------------------------------------------------------------------------
selo_svg <- function(id_base,
                      texto_central = "INSPECIONADO",
                      texto_topo = "SECRETARIA DE AGRICULTURA",
                      texto_base = "DISTRITO FEDERAL",
                      linha2 = "DIPOVA - SID",
                      numero = "000",
                      formato = c("oval_grande", "oval_pequeno", "retangular"),
                      cor_traço = "#1A1A1A") {
  formato <- match.arg(formato)
  # Fonte estilo "carimbo" (serifada/mono, como nos modelos oficiais)
  fonte <- "'Courier New', Courier, monospace"

  # ---------------------------------------------------------------------
  # MODELO RETANGULAR (Modelo 3): borda única, texto reto (sem curvatura)
  # ---------------------------------------------------------------------
  if (formato == "retangular") {
    svg <- sprintf('
      <svg viewBox="0 0 220 160" xmlns="http://www.w3.org/2000/svg" style="width:100%%;max-width:190px;">
        <rect x="5" y="5" width="210" height="150" fill="none" stroke="%s" stroke-width="1.3"/>
        <text x="110" y="24" text-anchor="middle" font-family="%s" font-size="8.5" font-weight="700" fill="%s" letter-spacing="0.8">%s</text>
        <text x="110" y="70" text-anchor="middle" font-family="%s" font-size="20" font-weight="700" fill="%s" letter-spacing="1" style="text-decoration:underline;">%s</text>
        <text x="110" y="92" text-anchor="middle" font-family="%s" font-size="10.5" font-weight="600" fill="%s" letter-spacing="0.5">%s</text>
        <text x="110" y="107" text-anchor="middle" font-family="%s" font-size="10.5" font-weight="600" fill="%s">%s</text>
        <text x="110" y="142" text-anchor="middle" font-family="%s" font-size="9" font-weight="700" fill="%s" letter-spacing="0.8">%s</text>
      </svg>',
      cor_traço,
      fonte, cor_traço, texto_topo,
      fonte, cor_traço, texto_central,
      fonte, cor_traço, linha2,
      fonte, cor_traço, numero,
      fonte, cor_traço, texto_base
    )
    return(HTML(svg))
  }

  # ---------------------------------------------------------------------
  # MODELOS OVAIS (1, 2, 4, 5): borda única + texto curvo no topo e na base
  # ---------------------------------------------------------------------
  grande <- formato == "oval_grande"
  rx    <- if (grande) 100 else 84
  ry    <- if (grande) 62  else 56
  cx <- 110; cy <- if (grande) 88 else 84
  rx_t  <- if (grande) 88 else 71   # raio (x) do texto curvo — próximo da borda, como no original
  ry_t  <- if (grande) 54 else 47   # raio (y) do texto curvo
  fs_curva   <- if (grande) 8.5 else 7.3
  # texto central menor quando a palavra é mais longa (ex.: REINSPECIONADO), para não estourar o oval
  n_chars <- nchar(texto_central)
  fs_central <- if (grande) {
    if (n_chars > 12) 15 else 18
  } else {
    if (n_chars > 12) 11.5 else 14.5
  }

  path_id_top <- paste0("curvatopo_", id_base)
  path_id_bot <- paste0("curvabase_", id_base)

  y_central <- cy - 2
  y_linha2  <- cy + 15
  y_numero  <- cy + 29

  svg <- sprintf('
    <svg viewBox="0 0 220 176" xmlns="http://www.w3.org/2000/svg" style="width:100%%;max-width:190px;">
      <defs>
        <path id="%s" d="M %d %d A %d %d 0 0 1 %d %d" fill="none"/>
        <path id="%s" d="M %d %d A %d %d 0 0 0 %d %d" fill="none"/>
      </defs>
      <ellipse cx="%d" cy="%d" rx="%d" ry="%d" fill="none" stroke="%s" stroke-width="1.3"/>
      <text font-family="%s" font-size="%s" font-weight="700" fill="%s" letter-spacing="0.6">
        <textPath href="#%s" startOffset="50%%" text-anchor="middle">%s</textPath>
      </text>
      <text font-family="%s" font-size="%s" font-weight="700" fill="%s" letter-spacing="0.6">
        <textPath href="#%s" startOffset="50%%" text-anchor="middle">%s</textPath>
      </text>
      <text x="%d" y="%d" text-anchor="middle" font-family="%s" font-size="%s" font-weight="700" fill="%s" letter-spacing="0.5" style="text-decoration:underline;">%s</text>
      <text x="%d" y="%d" text-anchor="middle" font-family="%s" font-size="9.5" font-weight="600" fill="%s" letter-spacing="0.3">%s</text>
      <text x="%d" y="%d" text-anchor="middle" font-family="%s" font-size="9.5" font-weight="600" fill="%s">%s</text>
    </svg>',
    path_id_top, cx - rx_t, cy, rx_t, ry_t, cx + rx_t, cy,
    path_id_bot, cx - rx_t, cy, rx_t, ry_t, cx + rx_t, cy,
    cx, cy, rx, ry, cor_traço,
    fonte, fs_curva, cor_traço, path_id_top, texto_topo,
    fonte, fs_curva, cor_traço, path_id_bot, texto_base,
    cx, y_central, fonte, fs_central, cor_traço, texto_central,
    cx, y_linha2, fonte, cor_traço, linha2,
    cx, y_numero, fonte, cor_traço, numero
  )
  HTML(svg)
}

# -----------------------------------------------------------------------------
# 8. CSS GERAL DO APP
# -----------------------------------------------------------------------------
css_geral <- sprintf('
  body { background:%s; color:%s; font-family: "Segoe UI", "Helvetica Neue", Arial, sans-serif; }

  .capa-manual {
    background: linear-gradient(135deg, %s 0%%, %s 100%%);
    color:#fff; border-radius:18px; padding:46px 36px; margin-bottom:26px;
    box-shadow:0 10px 30px rgba(0,0,0,0.25);
  }
  .capa-manual .tag-topo {
    letter-spacing:3px; font-size:12px; font-weight:700; color:%s; margin-bottom:14px;
  }
  .capa-manual h1 { font-size:40px; font-weight:800; margin:0 0 6px 0; }
  .capa-manual h1 span { color:%s; }
  .capa-manual p.sub { font-size:15px; opacity:0.92; max-width:640px; }

  .sidebar-manual {
    background:%s; border-radius:16px; padding:18px 10px; position:sticky; top:16px;
  }
  .nav-pills>li>a {
    color:%s !important; border-radius:10px !important; font-weight:600; font-size:13.5px;
    padding:10px 14px !important; margin-bottom:4px;
  }
  .nav-pills>li.active>a, .nav-pills>li.active>a:hover, .nav-pills>li.active>a:focus {
    background: %s !important; color:#fff !important;
    box-shadow:0 4px 10px rgba(0,0,0,0.2);
  }
  .nav-pills>li>a:hover { background:%s55 !important; }

  .secao-titulo {
    display:flex; align-items:center; border-bottom:3px solid %s;
    padding-bottom:10px; margin-bottom:22px; margin-top:4px;
  }
  .secao-titulo h2 { color:%s; font-weight:800; margin:0; font-size:26px; }
  .secao-tag {
    display:inline-block; background:%s; color:#fff; font-size:11px; font-weight:700;
    letter-spacing:1.5px; padding:4px 12px; border-radius:20px; margin-bottom:10px;
  }

  .card-manual {
    background:#fff; border-radius:14px; padding:22px 24px; margin-bottom:20px;
    box-shadow:0 3px 14px rgba(18,53,36,0.08); border:1px solid #eee;
  }
  .card-manual h4 { color:%s; font-weight:700; border-left:4px solid %s; padding-left:10px; margin-bottom:14px;}

  .tabela-manual { width:100%%; border-collapse:collapse; margin:14px 0; font-size:13.5px; }
  .tabela-manual th {
    background:%s; color:#fff; text-align:left; padding:10px 12px; font-weight:700;
  }
  .tabela-manual td { padding:10px 12px; border-bottom:1px solid #eee; }
  .tabela-manual tr:nth-child(even) td { background:%s; }

  .btn-link-dourado {
    background: linear-gradient(135deg, %s, %s); color:#fff !important; font-weight:700;
    padding:8px 16px; border-radius:8px; text-decoration:none !important; font-size:13px;
    white-space:nowrap;
  }
  .btn-link-dourado:hover { opacity:0.88; }

  .selo-caixa {
    background:#fff; border-radius:14px; padding:16px; text-align:center;
    box-shadow:0 3px 10px rgba(0,0,0,0.08); border:1px solid #eee;
  }
  .selo-caixa .selo-legenda { margin-top:8px; font-weight:700; color:%s; font-size:13px; }

  .contato-box {
    background: linear-gradient(135deg, %s, %s); color:#fff; border-radius:16px;
    padding:26px 28px;
  }
  .contato-box a { color:%s; font-weight:700; text-decoration:none; }
  .rodape-manual {
    text-align:center; padding:22px; color:%s; font-size:12.5px; opacity:0.85;
  }
', cor_creme, cor_texto,
   cor_grafite_escuro, cor_grafite_medio, cor_dourado, cor_dourado,
   cor_grafite_claro, cor_grafite_escuro, cor_grafite_escuro, cor_grafite_claro,
   cor_dourado, cor_grafite_escuro, cor_grafite_medio,
   cor_grafite_escuro, cor_grafite_medio,
   cor_grafite_medio, cor_grafite_claro,
   cor_dourado, cor_dourado_escuro,
   cor_grafite_escuro,
   cor_grafite_medio, cor_grafite_escuro, cor_dourado,
   cor_grafite_escuro
)

# =============================================================================
# UI
# =============================================================================
ui <- fluidPage(
  title = "Manual para Registro — DIPOVA/SEAGRI-DF",
  tags$head(tags$style(HTML(css_geral))),

  # ---------- CAPA ----------
  div(
    class = "capa-manual",
    div(class = "tag-topo", "DIPOVA · SEAGRI-DF · PRIMEIRA VERSÃO 2026"),
    tags$h1("MANUAL PARA ", tags$span("REGISTRO")),
    tags$p(class = "sub",
      "Passo a passo detalhado para agroindústrias de produtos de origem animal. ",
      "Como preparar sua documentação e preencher os formulários corretamente junto ao Serviço de Inspeção Distrital."
    ),
    tags$p(style = "margin-top:16px;font-weight:700;",
      "Secretaria de Estado da Agricultura, Abastecimento e Desenvolvimento Rural do DF — SEAGRI/DF")
  ),

  fluidRow(
    # ---------- MENU LATERAL ----------
    column(
      width = 3,
      div(
        class = "sidebar-manual",
        navlistPanel(
          id = "menu_principal", well = FALSE, widths = c(12, 12),
          tabPanel("01 · Checklist Inicial", value = "checklist"),
          tabPanel("02 · Etapa 1 — Requerimentos", value = "etapa1"),
          tabPanel("03 · Etapa 2 — Projeto de Construção", value = "etapa2"),
          tabPanel("04 · Etapa 3 — Memorial Descritivo", value = "etapa3"),
          tabPanel("05 · Etapa 4 — Registro de Rótulos", value = "etapa4"),
          tabPanel("06 · Etapa 5 — Autocontrole (PAC)", value = "etapa5"),
          tabPanel("07 · Etapa Final — Vistoria e Selo", value = "etapafinal"),
          tabPanel("08 · Protocolo e Prazos", value = "protocolo"),
          tabPanel("09 · Dúvidas e Contato", value = "contato")
        )
      )
    ),

    # ---------- CONTEÚDO ----------
    column(
      width = 9,
      uiOutput("conteudo_secao")
    )
  ),

  div(class = "rodape-manual",
    tags$hr(),
    "GOVERNO DO DISTRITO FEDERAL — Secretaria de Estado da Agricultura, Abastecimento e Desenvolvimento Rural — SEAGRI/DF DIPOVA — Diretoria de Inspeção de Produtos de Origem Vegetal e Animal.", tags$br(),
    tags$em('"Produzir com qualidade é valorizar o campo e respeitar o consumidor."')
  )
)

# =============================================================================
# SERVER
# =============================================================================
server <- function(input, output, session) {
  output$conteudo_secao <- renderUI({
    switch(input$menu_principal,

      # -----------------------------------------------------------------------
      # 01 · Checklist Inicial — conteúdo do app original
      # -----------------------------------------------------------------------
      "checklist" = tagList(
        div(class = "secao-titulo", tags$h2("Checklist Inicial: o que você precisa?")),
        div(class = "card-manual",
          p("Antes de iniciar o preenchimento dos formulários, certifique-se de que possui os seguintes documentos e informações básicas organizadas."),
          h4("Documentos da Empresa / Produtor"),
          item_check("CPF ou CNPJ + Inscrição Estadual."),
          item_check(tags$b("Pessoa Jurídica:"), " A empresa deve estar inscrita no Sistema de Registro e Licenciamento de Empresas (RLE) com viabilidade de localização deferida (obrigatório para grande/médio porte)."),
          item_check(tags$b("Pessoa Física:"), " Apresentar o CPF e documento com foto."),
          caixa_destaque("ATENÇÃO — CNAE", tipo = "atencao",
            "O CNAE do CNPJ deve ser o da atividade a ser licenciada pela SEAGRI. Sem isso, o registro na Junta Comercial e a obtenção da licença de funcionamento ficam comprometidos."),
          h4("Viabilidade de localização"),
          p("Para autorizar a abertura de uma indústria no DF, o interessado deve emitir a Viabilidade de Localização. O processo é digital, pelo portal RLE@Digital, onde a Administração Regional analisa se o lote comporta o CNAE escolhido."),
          caixa_destaque("ATENÇÃO", tipo = "atencao", "Obrigatório apenas para estabelecimentos de médio e grande porte."),
          h4("Licenciamento ambiental e outros"),
          p("Licença ou dispensa emitida pelos órgãos competentes. Para orientações sobre os documentos exigidos e os procedimentos aplicáveis, orienta-se consultar o sítio eletrônico oficial de cada órgão responsável. O registro na SEAGRI-DF não dispensa o licenciamento em outros órgãos."),
          h4("Laudo da água"),
          p("Análise laboratorial recente comprovando a potabilidade da água utilizada. Referência: PORTARIA GM/MS Nº 888, de 4 de maio de 2021 (Ministério da Saúde)."),
          h4("Responsável Técnico (RT)"),
          p("Contrato e ART — Anotação de Responsabilidade Técnica do profissional habilitado. Para agroindústrias de pequeno porte só será obrigatório se o estabelecimento for abatedouro."),
          caixa_destaque("Dica de Ouro", tipo = "dica",
            "Organize tudo em uma pasta digital ou física. A falta de qualquer um desses itens impedirá a conclusão do seu registro na DIPOVA.")
        )
      ),

      # -----------------------------------------------------------------------
      # 02 · Etapa 1 — Requerimentos
      # -----------------------------------------------------------------------
      "etapa1" = tagList(
        div(class = "secao-titulo", tags$h2(badge_numero(1), "Etapa 1 — Requerimentos Iniciais")),
        div(class = "card-manual",
          h4("Guia de Registro no Serviço de Inspeção Distrital"),
          p("Para dar início ao registro da agroindústria junto à DIPOVA/SEAGRI-DF, deverão ser preenchidos os termos exemplificados neste passo a passo e enviados para:"),
          div(style = sprintf("background:%s;color:#fff;padding:14px 18px;border-radius:10px;margin:14px 0;", cor_grafite_escuro),
            tags$b("✉ E-mail de envio: "), tags$a(style = sprintf("color:%s;", cor_dourado), href=paste0("mailto:", email_geinsp), email_geinsp),
            tags$br(), "Envie todos os documentos preenchidos para este endereço."),
          h4("Requerimentos a enviar"),
          item_check("1 - Requerimento de vistoria prévia para registro de estabelecimento."),
          item_check("2 - Requerimento para registro de estabelecimento."),
          h4("Como preencher corretamente"),
          p("Baixe o arquivo PDF editável e preencha com seus dados pessoais: ", tags$b("Nome, RG, CPF e endereço residencial"), ". Inclua também os dados do estabelecimento: razão social, localização, CNPJ, Inscrição Estadual e ", tags$b("classificação do estabelecimento"), " desejado."),
          h4("Acesse os requerimentos"),
          cartao_link("Requerimentos de vistoria prévia e de registro de estabelecimento", link_requerimentos)
        ),
        div(class = "card-manual",
          h4("Informações importantes"),
          caixa_destaque("Contato", tipo = "dica", "Após enviar os documentos, aguarde o contato dos fiscais para agendamento da vistoria, não se esqueça de preencher o telefone e o email para contato."),
          caixa_destaque("Assinatura", tipo = "dica", "A assinatura deve ser idêntica à do documento de identidade (RG/CNH). Se assinado digitalmente, utilize o padrão Gov.br ou outra forma de autenticação.")
        ),
        div(class = "card-manual",
          h4("Categorias de estabelecimento - Médio e grande porte (Decreto 38981/2018 e alterações)"),
          tabela_estilizada(
            c("Categoria", "Médio e grande porte (Decreto 38981/2018 e alterações)"),
            list(
              list("Leite e Derivados", "Unidade de beneficiamento de leite e derivados; queijaria; granja leiteira."),
              list("Carne e Produtos cárneos", "Abatedouro frigorífico; unidade de beneficiamento de carne e produtos cárneos."),
              list("Pescado e Derivados", "Abatedouro frigorífico de pescado; unidade de beneficiamento de pescado e produtos de pescado."),
              list("Ovos e Derivados", "Unidade de beneficiamento de ovos e derivados; granja avícola."),
              list("Mel e Produtos Agrícolas", "Unidade de beneficiamento de produtos de abelhas.")
            )
          )
        ),
