# -----------------------------------------------------------------------------
# 3. FUNÇÃO AUXILIAR — caixa de destaque (dica / atenção / info)
# -----------------------------------------------------------------------------
caixa_destaque <- function(titulo, ..., tipo = c("dica", "atencao", "perigo", "info")) {
  tipo <- match.arg(tipo)
  estilos <- list(
    dica    = list(bg = cor_grafite_claro, borda = cor_grafite_medio, icone = "\U0001F4A1"),
    atencao = list(bg = cor_alerta_bg,   borda = cor_alerta_borda, icone = "\u26A0\uFE0F"),
    perigo  = list(bg = cor_perigo_bg,   borda = cor_perigo_borda, icone = "\u26D4"),
    info    = list(bg = cor_info_bg,     borda = cor_info_borda,  icone = "\u2139\uFE0F")
  )
  e <- estilos[[tipo]]
  div(
    style = sprintf(
      "background:%s; border-left:5px solid %s; border-radius:10px;
       padding:16px 18px; margin:14px 0;", e$bg, e$borda
    ),
    tags$strong(paste(e$icone, titulo)),
    div(style = "margin-top:6px; line-height:1.55;", ...)
  )
}

