# -----------------------------------------------------------------------------
# 6. FUNÇÃO AUXILIAR — tabela estilizada simples a partir de uma matriz/lista
# -----------------------------------------------------------------------------
tabela_estilizada <- function(cabecalho, linhas) {
  tags$table(
    class = "tabela-manual",
    tags$thead(
      tags$tr(lapply(cabecalho, function(h) tags$th(h)))
    ),
    tags$tbody(
      lapply(linhas, function(linha) {
        tags$tr(lapply(linha, function(cel) tags$td(cel)))
      })
    )
  )
}

# -----------------------------------------------------------------------------
# 7. SELOS DA INSPEÇÃO DISTRITAL — desenhados em SVG (texto sobre caminho)
#    Cada selo recebe um "id_base" ÚNICO para evitar conflito de <path> no DOM
# -----------------------------------------------------------------------------
selo_svg <- function(id_base,
                      texto_central = "INSPECIONADO",
                      texto_topo = "SECRETARIA DE AGRICULTURA",
                      texto_base = "DISTRITO FEDERAL",
                      linha2 = "DIPOVA - SID",
                      numero = "000",
                      formato = c("oval_grande", "oval_pequeno", "retangular"),
                      cor_traço = "#1A1A1A") {
  formato <- match.arg(formato)
  # Fonte estilo "carimbo" (serifada/mono, como nos modelos oficiais)
  fonte <- "'Courier New', Courier, monospace"

  # ---------------------------------------------------------------------
  # MODELO RETANGULAR (Modelo 3): borda única, texto reto (sem curvatura)
  # ---------------------------------------------------------------------
  if (formato == "retangular") {
    svg <- sprintf('
      <svg viewBox="0 0 220 160" xmlns="http://www.w3.org/2000/svg" style="width:100%%;max-width:190px;">
        <rect x="5" y="5" width="210" height="150" fill="none" stroke="%s" stroke-width="1.3"/>
        <text x="110" y="24" text-anchor="middle" font-family="%s" font-size="8.5" font-weight="700" fill="%s" letter-spacing="0.8">%s</text>
        <text x="110" y="70" text-anchor="middle" font-family="%s" font-size="20" font-weight="700" fill="%s" letter-spacing="1" style="text-decoration:underline;">%s</text>
        <text x="110" y="92" text-anchor="middle" font-family="%s" font-size="10.5" font-weight="600" fill="%s" letter-spacing="0.5">%s</text>
        <text x="110" y="107" text-anchor="middle" font-family="%s" font-size="10.5" font-weight="600" fill="%s">%s</text>
        <text x="110" y="142" text-anchor="middle" font-family="%s" font-size="9" font-weight="700" fill="%s" letter-spacing="0.8">%s</text>
      </svg>',
      cor_traço,
      fonte, cor_traço, texto_topo,
      fonte, cor_traço, texto_central,
      fonte, cor_traço, linha2,
      fonte, cor_traço, numero,
      fonte, cor_traço, texto_base
    )
    return(HTML(svg))
  }

  # ---------------------------------------------------------------------
  # MODELOS OVAIS (1, 2, 4, 5): borda única + texto curvo no topo e na base
  # ---------------------------------------------------------------------
  grande <- formato == "oval_grande"
  rx    <- if (grande) 100 else 84
  ry    <- if (grande) 62  else 56
  cx <- 110; cy <- if (grande) 88 else 84
  rx_t  <- if (grande) 88 else 71   # raio (x) do texto curvo — próximo da borda, como no original
  ry_t  <- if (grande) 54 else 47   # raio (y) do texto curvo
  fs_curva   <- if (grande) 8.5 else 7.3
  # texto central menor quando a palavra é mais longa (ex.: REINSPECIONADO), para não estourar o oval
  n_chars <- nchar(texto_central)
  fs_central <- if (grande) {
    if (n_chars > 12) 15 else 18
  } else {
    if (n_chars > 12) 11.5 else 14.5
  }

  path_id_top <- paste0("curvatopo_", id_base)
  path_id_bot <- paste0("curvabase_", id_base)

  y_central <- cy - 2
  y_linha2  <- cy + 15
  y_numero  <- cy + 29

  svg <- sprintf('
    <svg viewBox="0 0 220 176" xmlns="http://www.w3.org/2000/svg" style="width:100%%;max-width:190px;">
      <defs>
        <path id="%s" d="M %d %d A %d %d 0 0 1 %d %d" fill="none"/>
        <path id="%s" d="M %d %d A %d %d 0 0 0 %d %d" fill="none"/>
      </defs>
      <ellipse cx="%d" cy="%d" rx="%d" ry="%d" fill="none" stroke="%s" stroke-width="1.3"/>
      <text font-family="%s" font-size="%s" font-weight="700" fill="%s" letter-spacing="0.6">
        <textPath href="#%s" startOffset="50%%" text-anchor="middle">%s</textPath>
      </text>
      <text font-family="%s" font-size="%s" font-weight="700" fill="%s" letter-spacing="0.6">
        <textPath href="#%s" startOffset="50%%" text-anchor="middle">%s</textPath>
      </text>
      <text x="%d" y="%d" text-anchor="middle" font-family="%s" font-size="%s" font-weight="700" fill="%s" letter-spacing="0.5" style="text-decoration:underline;">%s</text>
      <text x="%d" y="%d" text-anchor="middle" font-family="%s" font-size="9.5" font-weight="600" fill="%s" letter-spacing="0.3">%s</text>
      <text x="%d" y="%d" text-anchor="middle" font-family="%s" font-size="9.5" font-weight="600" fill="%s">%s</text>
    </svg>',
    path_id_top, cx - rx_t, cy, rx_t, ry_t, cx + rx_t, cy,
    path_id_bot, cx - rx_t, cy, rx_t, ry_t, cx + rx_t, cy,
    cx, cy, rx, ry, cor_traço,
    fonte, fs_curva, cor_traço, path_id_top, texto_topo,
    fonte, fs_curva, cor_traço, path_id_bot, texto_base,
    cx, y_central, fonte, fs_central, cor_traço, texto_central,
    cx, y_linha2, fonte, cor_traço, linha2,
    cx, y_numero, fonte, cor_traço, numero
  )
  HTML(svg)
}

